UPDATE vocabulary SET example_jp = '飲み物に氷を入れすぎると、味が薄くなります。', example_reading = NULL, example_vi = 'Cho quá nhiều đá vào đồ uống sẽ làm nhạt vị.' WHERE vocabulary_id = 192409;
UPDATE vocabulary SET example_jp = '夜になると急に冷えるので、上着を持って行きます。', example_reading = NULL, example_vi = 'Đêm xuống trời lạnh nhanh nên tôi mang áo khoác.' WHERE vocabulary_id = 192410;
