UPDATE vocabulary SET example_jp = '真夏日には外を長く歩かず、十分に水を飲みます。', example_reading = NULL, example_vi = 'Ngày trên 30 độ tôi không đi lâu ngoài trời và uống đủ nước.' WHERE vocabulary_id = 192413;
