UPDATE vocabulary SET example_jp = '今朝は冬日で、車の窓が凍っていました。', example_reading = NULL, example_vi = 'Sáng nay nhiệt độ xuống dưới không độ, kính xe đóng băng.' WHERE vocabulary_id = 192415;
UPDATE vocabulary SET example_jp = '真冬日には昼でも気温が上がらず、外がとても寒いです。', example_reading = NULL, example_vi = 'Ngày rét cả ngày dưới không độ, buổi trưa ngoài trời vẫn lạnh.' WHERE vocabulary_id = 192416;
UPDATE vocabulary SET example_jp = '今年は暖冬で、去年ほど雪が降りませんでした。', example_reading = NULL, example_vi = 'Mùa đông năm nay ấm nên không có nhiều tuyết như năm ngoái.' WHERE vocabulary_id = 192417;
UPDATE vocabulary SET example_jp = '冷夏の影響で、今年は夏の野菜があまり育ちませんでした。', example_reading = NULL, example_vi = 'Mùa hè mát bất thường khiến rau mùa hè năm nay kém phát triển.' WHERE vocabulary_id = 192418;
UPDATE vocabulary SET example_jp = '古い橋の状態を調べてから、修理を始めます。', example_reading = NULL, example_vi = 'Chúng tôi kiểm tra tình trạng cầu cũ rồi mới sửa.' WHERE vocabulary_id = 192419;
UPDATE vocabulary SET example_jp = '十年前と比べると、この町は大きく変化しました。', example_reading = NULL, example_vi = 'So với mười năm trước, thị trấn này đã thay đổi nhiều.' WHERE vocabulary_id = 192420;
UPDATE vocabulary SET example_jp = '部屋の温度を一定に保つため、暖房を調節します。', example_reading = NULL, example_vi = 'Tôi điều chỉnh máy sưởi để giữ nhiệt độ phòng ổn định.' WHERE vocabulary_id = 192421;
UPDATE vocabulary SET example_jp = '毎朝、庭の植物を観察して変化を記録します。', example_reading = NULL, example_vi = 'Mỗi sáng tôi quan sát cây trong vườn và ghi lại thay đổi.' WHERE vocabulary_id = 192422;
UPDATE vocabulary SET example_jp = '春が近づくにつれて、次第に暖かくなってきました。', example_reading = NULL, example_vi = 'Xuân đến gần, trời dần ấm lên.' WHERE vocabulary_id = 192423;
UPDATE vocabulary SET example_jp = '授業が終わってから、レポートを一気に書き上げました。', example_reading = NULL, example_vi = 'Sau giờ học, tôi viết một mạch xong báo cáo.' WHERE vocabulary_id = 192424;
UPDATE vocabulary SET example_jp = '予定が重なり、三つの仕事を一度に頼まれました。', example_reading = NULL, example_vi = 'Lịch trùng nhau, tôi bị giao ba việc cùng lúc.' WHERE vocabulary_id = 192425;
UPDATE vocabulary SET example_jp = '忙しくしているうちに、いつの間にか夜になっていました。', example_reading = NULL, example_vi = 'Mải bận rộn, tôi không biết trời đã tối từ lúc nào.' WHERE vocabulary_id = 192426;
