UPDATE vocabulary SET example_jp = '機械から変な音がするので、使うのをやめました。', example_reading = NULL, example_vi = 'Máy phát tiếng lạ nên tôi ngừng dùng.' WHERE vocabulary_id = 192428;
UPDATE vocabulary SET example_jp = '来週の月曜日は祝日なので、学校が休みです。', example_reading = NULL, example_vi = 'Thứ Hai tuần sau là ngày lễ nên trường nghỉ.' WHERE vocabulary_id = 192429;
UPDATE vocabulary SET example_jp = '年末年始は家族と過ごすため、早めに切符を予約します。', example_reading = NULL, example_vi = 'Tôi đặt vé sớm để ở bên gia đình dịp cuối năm đầu năm.' WHERE vocabulary_id = 192430;
UPDATE vocabulary SET example_jp = '元日の朝は家族で新年の挨拶をします。', example_reading = NULL, example_vi = 'Sáng mồng một Tết, cả nhà chúc nhau năm mới.' WHERE vocabulary_id = 192431;
UPDATE vocabulary SET example_jp = '友達を空港で迎えてから、一緒に町を歩きました。', example_reading = NULL, example_vi = 'Tôi đón bạn ở sân bay rồi cùng dạo thành phố.' WHERE vocabulary_id = 192432;
UPDATE vocabulary SET example_jp = '昔の先生から年賀状が届いて、とても懐かしくなりました。', example_reading = NULL, example_vi = 'Nhận thiệp năm mới từ thầy cũ, tôi thấy rất nhớ ngày xưa.' WHERE vocabulary_id = 192433;
UPDATE vocabulary SET example_jp = '子どもたちはお年玉をもらって、うれしそうでした。', example_reading = NULL, example_vi = 'Bọn trẻ nhận tiền mừng tuổi, trông rất vui.' WHERE vocabulary_id = 192434;
UPDATE vocabulary SET example_jp = '成人の日には、新成人がきれいな着物を着ているのを見ました。', example_reading = NULL, example_vi = 'Vào Ngày Thành nhân, tôi thấy những người vừa trưởng thành mặc kimono đẹp.' WHERE vocabulary_id = 192435;
UPDATE vocabulary SET example_jp = 'ひな祭りには、娘のために人形を飾ります。', example_reading = NULL, example_vi = 'Dịp lễ Hina, tôi bày búp bê cho con gái.' WHERE vocabulary_id = 192436;
UPDATE vocabulary SET example_jp = '子どもの日は、家族で子どもの成長を祝います。', example_reading = NULL, example_vi = 'Ngày Trẻ em, cả nhà mừng con lớn lên.' WHERE vocabulary_id = 192437;
UPDATE vocabulary SET example_jp = '母の日に花を贈ったら、母がとても喜んでくれました。', example_reading = NULL, example_vi = 'Tặng hoa Ngày của Mẹ, mẹ tôi rất vui.' WHERE vocabulary_id = 192438;
UPDATE vocabulary SET example_jp = '父の日には父の好きな本をプレゼントするつもりです。', example_reading = NULL, example_vi = 'Ngày của Bố tôi định tặng cuốn sách bố thích.' WHERE vocabulary_id = 192439;
UPDATE vocabulary SET example_jp = '海の日の連休に、友達と海岸へ遊びに行きました。', example_reading = NULL, example_vi = 'Kỳ nghỉ Ngày của Biển, tôi đi chơi bờ biển với bạn.' WHERE vocabulary_id = 192440;
UPDATE vocabulary SET example_jp = '敬老の日には、祖父母に電話して近況を聞きます。', example_reading = NULL, example_vi = 'Ngày Kính lão, tôi gọi hỏi thăm ông bà.' WHERE vocabulary_id = 192441;
UPDATE vocabulary SET example_jp = '体育の日には、近くの公園で家族と運動しました。', example_reading = NULL, example_vi = 'Ngày Thể dục thể thao, tôi vận động cùng gia đình ở công viên.' WHERE vocabulary_id = 192442;
UPDATE vocabulary SET example_jp = '七五三の日、子どもは着物を着て神社へ行きました。', example_reading = NULL, example_vi = 'Vào lễ Shichi Go San, con tôi mặc kimono đến đền.' WHERE vocabulary_id = 192443;
UPDATE vocabulary SET example_jp = '大みそかは家族と一緒に、今年の出来事を振り返ります。', example_reading = NULL, example_vi = 'Đêm giao thừa, tôi cùng gia đình nhìn lại chuyện trong năm.' WHERE vocabulary_id = 192444;
UPDATE vocabulary SET example_jp = '電話ではうまく伝わらなかったので、会って直接説明することにしました。', example_reading = NULL, example_vi = 'Vì qua điện thoại không truyền đạt rõ được nên tôi quyết định gặp để giải thích trực tiếp.' WHERE vocabulary_id = 192445;
UPDATE vocabulary SET example_jp = '今朝読んだ記事によると、この町に新しい図書館ができるそうです。', example_reading = NULL, example_vi = 'Theo bài báo tôi đọc sáng nay, thị trấn này sắp có thư viện mới.' WHERE vocabulary_id = 192446;
