UPDATE vocabulary SET example_jp = 'その政治家は市民の意見を聞くために、駅前で話をしました。', example_reading = NULL, example_vi = 'Chính trị gia đó phát biểu trước ga để lắng nghe ý kiến người dân.' WHERE vocabulary_id = 192448;
UPDATE vocabulary SET example_jp = '政府は物価が上がっていることについて、来週説明する予定です。', example_reading = NULL, example_vi = 'Chính phủ dự định giải thích vào tuần tới về việc giá cả đang tăng.' WHERE vocabulary_id = 192449;
UPDATE vocabulary SET example_jp = '新しい公園を作る前に、市民の声をもっと聞いてほしいです。', example_reading = NULL, example_vi = 'Trước khi xây công viên mới, tôi muốn họ lắng nghe người dân nhiều hơn.' WHERE vocabulary_id = 192450;
UPDATE vocabulary SET example_jp = '相手の立場になって考えると、なぜ怒ったのか少し分かります。', example_reading = NULL, example_vi = 'Khi đặt mình vào vị trí của người kia, tôi hiểu phần nào vì sao họ giận.' WHERE vocabulary_id = 192451;
