UPDATE vocabulary SET example_jp = '健康は重要ですから、忙しくても食事を抜かないようにしています。', example_reading = NULL, example_vi = 'Sức khỏe rất quan trọng nên dù bận tôi vẫn cố không bỏ bữa.' WHERE vocabulary_id = 192454;
UPDATE vocabulary SET example_jp = '雨は降っていましたが、大して強くなかったので歩いて帰りました。', example_reading = NULL, example_vi = 'Trời có mưa nhưng không lớn lắm nên tôi đã đi bộ về.' WHERE vocabulary_id = 192455;
UPDATE vocabulary SET example_jp = '司会者が質問を分かりやすくまとめてくれたので、話が聞きやすかったです。', example_reading = NULL, example_vi = 'Người dẫn chương trình tóm tắt câu hỏi dễ hiểu nên buổi trò chuyện rất dễ theo dõi.' WHERE vocabulary_id = 192456;
UPDATE vocabulary SET example_jp = '試合は生放送で見られるので、仕事が終わったらすぐ帰ります。', example_reading = NULL, example_vi = 'Vì có thể xem trận đấu trực tiếp nên tôi sẽ về ngay sau giờ làm.' WHERE vocabulary_id = 192457;
