UPDATE vocabulary SET example_jp = '来月発売される新しい本を、今から楽しみにしています。', example_reading = NULL, example_vi = 'Tôi đang mong chờ cuốn sách mới sẽ được phát hành tháng sau.' WHERE vocabulary_id = 192459;
UPDATE vocabulary SET example_jp = 'あの店は料理がおいしいと評判なので、週末は予約したほうがいいです。', example_reading = NULL, example_vi = 'Quán đó nổi tiếng đồ ăn ngon nên cuối tuần bạn nên đặt trước.' WHERE vocabulary_id = 192460;
UPDATE vocabulary SET example_jp = '新しい映画が注目されているので、公開されたら見に行きたいです。', example_reading = NULL, example_vi = 'Bộ phim mới đang được chú ý nên khi công chiếu tôi muốn đi xem.' WHERE vocabulary_id = 192461;
UPDATE vocabulary SET example_jp = 'いろいろ迷いましたが、結局駅に近い部屋を借りることにしました。', example_reading = NULL, example_vi = 'Tôi phân vân nhiều, nhưng cuối cùng quyết định thuê phòng gần ga.' WHERE vocabulary_id = 192462;
UPDATE vocabulary SET example_jp = '知らない人から怪しいメールが届いたので、開かずに消しました。', example_reading = NULL, example_vi = 'Có thư đáng ngờ từ người lạ gửi đến nên tôi đã xóa mà không mở.' WHERE vocabulary_id = 192463;
UPDATE vocabulary SET example_jp = '夜の山道は暗くて恐ろしかったので、急いで宿に戻りました。', example_reading = NULL, example_vi = 'Đường núi ban đêm tối và đáng sợ nên chúng tôi vội quay về chỗ nghỉ.' WHERE vocabulary_id = 192464;
