UPDATE vocabulary SET example_jp = '犯罪を防ぐために、夜は駅の周りを明るくするそうです。', example_reading = NULL, example_vi = 'Nghe nói họ sẽ làm khu vực quanh ga sáng hơn vào ban đêm để phòng tội phạm.' WHERE vocabulary_id = 192467;
UPDATE vocabulary SET example_jp = '発見者の話によると、なくした財布は公園のベンチにあったそうです。', example_reading = NULL, example_vi = 'Theo người phát hiện, chiếc ví bị mất nằm trên ghế ở công viên.' WHERE vocabulary_id = 192468;
UPDATE vocabulary SET example_jp = '友達を疑う前に、何があったのか本人に聞いてみました。', example_reading = NULL, example_vi = 'Trước khi nghi ngờ bạn, tôi đã hỏi trực tiếp xem chuyện gì xảy ra.' WHERE vocabulary_id = 192469;
UPDATE vocabulary SET example_jp = '警察は防犯カメラを調べて、犯人がどこへ行ったか確認しています。', example_reading = NULL, example_vi = 'Cảnh sát kiểm tra camera an ninh để xác định thủ phạm đã đi đâu.' WHERE vocabulary_id = 192470;
UPDATE vocabulary SET example_jp = '誰かが店の商品を盗むところを見て、すぐ店員に知らせました。', example_reading = NULL, example_vi = 'Thấy ai đó trộm hàng trong cửa tiệm, tôi báo ngay cho nhân viên.' WHERE vocabulary_id = 192471;
UPDATE vocabulary SET example_jp = 'なくした鍵を捜していたら、昨日着た上着のポケットから出てきました。', example_reading = NULL, example_vi = 'Đang tìm chìa khóa bị mất thì tôi thấy nó trong túi áo khoác mặc hôm qua.' WHERE vocabulary_id = 192472;
UPDATE vocabulary SET example_jp = '駅で走っていく子どもを母親が追っていましたが、すぐに見つかりました。', example_reading = NULL, example_vi = 'Người mẹ đuổi theo đứa trẻ chạy ở ga và đã tìm thấy con ngay.' WHERE vocabulary_id = 192473;
UPDATE vocabulary SET example_jp = '逃げた犬を近所の人が捕まえて、家まで連れてきてくれました。', example_reading = NULL, example_vi = 'Hàng xóm bắt được con chó chạy mất rồi đưa nó về nhà giúp tôi.' WHERE vocabulary_id = 192474;
UPDATE vocabulary SET example_jp = '駅で財布を盗んだ人が捕まったと、ニュースで聞きました。', example_reading = NULL, example_vi = 'Tôi nghe tin trên bản tin rằng kẻ lấy trộm ví ở ga đã bị bắt.' WHERE vocabulary_id = 192475;
UPDATE vocabulary SET example_jp = '警察は昨夜、店からお金を盗んだ疑いで男を逮捕しました。', example_reading = NULL, example_vi = 'Đêm qua cảnh sát bắt một người đàn ông vì nghi lấy trộm tiền của cửa hàng.' WHERE vocabulary_id = 192476;
UPDATE vocabulary SET example_jp = '暗い部屋から変な音がして、少し気味が悪くなりました。', example_reading = NULL, example_vi = 'Có tiếng động lạ từ căn phòng tối khiến tôi thấy hơi rợn.' WHERE vocabulary_id = 192477;
UPDATE vocabulary SET example_jp = '弟が自転車で事故にあったと聞いて、すぐ病院へ向かいました。', example_reading = NULL, example_vi = 'Nghe em trai gặp tai nạn xe đạp, tôi lập tức đến bệnh viện.' WHERE vocabulary_id = 192478;
UPDATE vocabulary SET example_jp = '大雨のため、山の近くで土砂崩れが発生したそうです。', example_reading = NULL, example_vi = 'Nghe nói do mưa lớn, một vụ sạt lở đã xảy ra gần núi.' WHERE vocabulary_id = 192479;
UPDATE vocabulary SET example_jp = '命に関わることなので、少しでも具合が悪ければ病院へ行ってください。', example_reading = NULL, example_vi = 'Vì đây là chuyện liên quan đến tính mạng, hễ thấy không khỏe dù chỉ một chút hãy đi bệnh viện.' WHERE vocabulary_id = 192480;
UPDATE vocabulary SET example_jp = '早く気づいて助けを呼んだおかげで、子どもの命を救えました。', example_reading = NULL, example_vi = 'Nhờ phát hiện sớm và gọi cứu hộ, họ đã cứu được mạng sống của đứa trẻ.' WHERE vocabulary_id = 192481;
UPDATE vocabulary SET example_jp = '事故の現場には人が集まっていたので、別の道を通りました。', example_reading = NULL, example_vi = 'Vì nhiều người tụ tập ở hiện trường tai nạn nên tôi đi đường khác.' WHERE vocabulary_id = 192482;
UPDATE vocabulary SET example_jp = '電車が急に止まって駅は混乱しましたが、係員が案内してくれました。', example_reading = NULL, example_vi = 'Tàu dừng đột ngột khiến nhà ga hỗn loạn, nhưng nhân viên đã hướng dẫn mọi người.' WHERE vocabulary_id = 192483;
UPDATE vocabulary SET example_jp = '台風の後、家族全員が無事だと分かって安心しました。', example_reading = NULL, example_vi = 'Sau cơn bão, biết cả gia đình đều bình an tôi mới yên tâm.' WHERE vocabulary_id = 192484;
UPDATE vocabulary SET example_jp = '風邪を防ぐために、帰宅したら手を洗うようにしています。', example_reading = NULL, example_vi = 'Để phòng cảm, tôi giữ thói quen rửa tay khi về nhà.' WHERE vocabulary_id = 192485;
UPDATE vocabulary SET example_jp = '道を間違えたので地図を確認し、再び駅に向かって歩きました。', example_reading = NULL, example_vi = 'Vì đi nhầm đường, tôi xem lại bản đồ rồi một lần nữa đi về phía ga.' WHERE vocabulary_id = 192486;
UPDATE vocabulary SET example_jp = '事故の被害者に何が必要か、担当者が一人ずつ聞いていました。', example_reading = NULL, example_vi = 'Người phụ trách đã hỏi từng nạn nhân vụ tai nạn xem họ cần gì.' WHERE vocabulary_id = 192487;
UPDATE vocabulary SET example_jp = 'お互いに忙しいけれど、週に一度は電話で近況を話します。', example_reading = NULL, example_vi = 'Dù cả hai đều bận, chúng tôi vẫn gọi điện kể tình hình cho nhau mỗi tuần một lần.' WHERE vocabulary_id = 192488;
UPDATE vocabulary SET example_jp = '説明を聞いても疑問が残ったので、先生にもう一度質問しました。', example_reading = NULL, example_vi = 'Dù đã nghe giải thích tôi vẫn còn thắc mắc nên hỏi lại giáo viên.' WHERE vocabulary_id = 192489;
UPDATE vocabulary SET example_jp = '子どもが川に飛び込もうとしたので、近くの大人が止めました。', example_reading = NULL, example_vi = 'Thấy đứa trẻ định nhảy xuống sông, người lớn ở gần đã ngăn lại.' WHERE vocabulary_id = 192490;
