UPDATE vocabulary SET example_jp = '雨で道が滑りやすくなっていたため、階段で転んでしまいました。', example_reading = NULL, example_vi = 'Do đường trơn vì mưa, tôi đã ngã trên cầu thang.' WHERE vocabulary_id = 192501;
