UPDATE vocabulary SET example_jp = '朝から断水しているので、料理をする前に水を買いに行きました。', example_reading = NULL, example_vi = 'Vì nước bị cắt từ sáng, tôi đi mua nước trước khi nấu ăn.' WHERE vocabulary_id = 192505;
