UPDATE vocabulary SET example_jp = 'この町では外国人の観光客が増加しているそうです。', example_reading = NULL, example_vi = 'Nghe nói số du khách nước ngoài ở thị trấn này đang tăng.' WHERE vocabulary_id = 192507;
UPDATE vocabulary SET example_jp = '子どもの数が減少しているため、この学校は来年閉まるそうです。', example_reading = NULL, example_vi = 'Vì số trẻ em giảm, nghe nói trường này sẽ đóng cửa vào năm sau.' WHERE vocabulary_id = 192508;
