UPDATE vocabulary SET example_jp = '不景気で客が減り、駅前の店がいくつか閉まりました。', example_reading = NULL, example_vi = 'Vì kinh tế suy thoái và khách giảm, vài cửa hàng trước ga đã đóng cửa.' WHERE vocabulary_id = 192515;
UPDATE vocabulary SET example_jp = '円高のため、日本から海外へ旅行する人が増えたそうです。', example_reading = NULL, example_vi = 'Nghe nói do đồng yên tăng giá, số người Nhật đi du lịch nước ngoài đã tăng.' WHERE vocabulary_id = 192516;
